// 1. قراءة المدخلات بأمان
let input = {};
try {
  if (typeof query === 'object' && query !== null) {
    input = query;
  } else if (typeof query === 'string') {
    input = JSON.parse(query);
  }
} catch (e) {
  input = {};
}

let cropName = (input.crop_name || '').toLowerCase().trim();
const tempC = parseFloat(input.temperature_c || 0);

// 2. خريطة تحويل الأسماء الشائعة والمفرد إلى الجمع المفهرس
const nameAliases = {
  "tomato": "tomatoes",
  "strawberry": "strawberries",
  "potato": "potatoes",
  "peach": "peaches",
  "flower": "flowers",
  "apple": "apples",
  "grape": "grapes",
  "almond": "almonds",
  "pistachio": "pistachios",
  "walnut": "walnuts",
  "peanut": "peanuts",
  "soybean": "soybeans",
  "oat": "oats"
};

// تحويل الاسم إذا كان مفردًا
if (nameAliases[cropName]) {
  cropName = nameAliases[cropName];
}

// 3. قاعدة البيانات الشاملة
const cropDatabase = {
  "corn": { ar: "الذرة", stress: 30, critical: 35, risk: "Risk of pollen viability loss and kernel abortion.", action: "Recommend pre-cooling irrigation before 8:00 AM." },
  "tomatoes": { ar: "الطماطم", stress: 29, critical: 34, risk: "Risk of blossom drop and sunscald.", action: "Recommend 30% shade netting and soil mulching." },
  "soybeans": { ar: "فول الصويا", stress: 32, critical: 38, risk: "Risk of pod abortion and reduced N-fixation.", action: "Recommend drip irrigation and avoiding peak-hour fertilization." },
  "lettuce": { ar: "الخص", stress: 24, critical: 28, risk: "Risk of early bolting and bitterness.", action: "Recommend overhead micro-misting and partial shading." },
  "strawberries": { ar: "الفراولة", stress: 26, critical: 30, risk: "Risk of fruit softening and reduced root division.", action: "Recommend drip irrigation and root-zone cooling." },
  "oats": { ar: "الشوفان", stress: 24, critical: 28, risk: "Risk of reduced tillering and panicle damage.", action: "Maintain soil moisture during vegetative stages." },
  "winter wheat": { ar: "قمح الشتاء", stress: 25, critical: 31, risk: "Risk of shortened grain filling period and starch loss.", action: "Recommend supplemental irrigation during grain filling." },
  "spring wheat": { ar: "قمح الربيع", stress: 24, critical: 30, risk: "Risk of floret sterility and yield reduction.", action: "Recommend early morning light irrigation." },
  "cover crops": { ar: "محاصيل التغطية", stress: 26, critical: 32, risk: "Risk of accelerated desiccation and biomass loss.", action: "Mow or incorporate into soil if seeding accelerates." },
  "sorghum": { ar: "السورغم", stress: 33, critical: 38, risk: "Risk of pollen sterility and head filling loss.", action: "Recommend soil cooling irrigation prior to flowering." },
  "sunflower": { ar: "عباد الشمس", stress: 31, critical: 36, risk: "Risk of reduced seed oil content.", action: "Recommend deep root-zone irrigation." },
  "cotton": { ar: "القطن", stress: 32, critical: 37, risk: "Risk of square shedding and reduced fiber quality.", action: "Recommend night irrigation and soil mulching." },
  "almonds": { ar: "اللوز", stress: 32, critical: 37, risk: "Risk of stigma desiccation and leaf drop.", action: "Recommend micro-sprinklers and Kaolin clay spray." },
  "pistachios": { ar: "الفستق", stress: 34, critical: 39, risk: "Risk of blank nut formation.", action: "Maintain optimal root zone hydration." },
  "walnuts": { ar: "الجوز", stress: 32, critical: 38, risk: "Risk of kernel darkening and sunburn.", action: "Recommend evaporative canopy cooling." },
  "rice": { ar: "الأرز", stress: 32, critical: 35, risk: "Risk of spikelet sterility during flowering.", action: "Increase flooding water depth to 10-15 cm." },
  "grapes": { ar: "العنب", stress: 31, critical: 36, risk: "Risk of anthocyanin degradation and leaf scorch.", action: "Manage canopy shade and apply canopy misting." },
  "citrus": { ar: "الحمضيات", stress: 33, critical: 38, risk: "Risk of fruitlet abortion (June drop).", action: "Recommend morning drip irrigation and trunk whitewashing." },
  "broccoli": { ar: "البروكلي", stress: 23, critical: 27, risk: "Risk of premature flowering and loose heads.", action: "Recommend misting and partial shading." },
  "greenhouse vegetables": { ar: "الخضراوات المغطاة", stress: 28, critical: 33, risk: "Risk of heat buildup and leaf burn.", action: "Activate greenhouse shade curtains and exhaust fans." },
  "peanuts": { ar: "الفول السوداني", stress: 31, critical: 36, risk: "Risk of peg penetration failure.", action: "Keep top-soil surface moist with frequent light irrigation." },
  "tobacco": { ar: "التبغ", stress: 30, critical: 35, risk: "Risk of leaf scalding and poor curing quality.", action: "Maintain constant soil moisture via drip lines." },
  "peaches": { ar: "الخوخ", stress: 30, critical: 35, risk: "Risk of fruit softening and skin cracking.", action: "Use under-canopy micro-sprinklers." },
  "apples": { ar: "التفاح", stress: 28, critical: 33, risk: "Risk of sunburn and flesh breakdown.", action: "Use evaporative cooling sprinklers and anti-transpirants." },
  "potatoes": { ar: "البطاطس", stress: 24, critical: 29, risk: "Risk of halted tuber initiation.", action: "Recommend root-zone cooling and heavy mulching." },
  "flowers": { ar: "الزهور", stress: 25, critical: 30, risk: "Risk of petal burning and shortened vase life.", action: "Use 40-50% shade netting and high-pressure fogging." },
  "hops": { ar: "القفزات", stress: 28, critical: 33, risk: "Risk of alpha-acid degradation.", action: "Optimize drip irrigation and apply canopy misting." },
  "barley": { ar: "الشعير", stress: 24, critical: 30, risk: "Risk of floret abortion and early decline.", action: "Irrigate during stem elongation and heading phases." }
};

const crop = cropDatabase[cropName];

if (!crop) {
  return JSON.stringify({ status: "UNKNOWN", message: `Crop '${cropName}' not found in database.` });
}

let status = "NORMAL";
if (tempC >= crop.critical) {
  status = "CRITICAL";
} else if (tempC >= crop.stress) {
  status = "STRESS";
}

return JSON.stringify({
  status: status,
  crop_ar: crop.ar,
  temperature_c: tempC,
  stress_threshold: crop.stress,
  critical_threshold: crop.critical,
  risk: status !== "NORMAL" ? crop.risk : "None. Crop is within safe temperature ranges.",
  action: status !== "NORMAL" ? crop.action : "Maintain standard watering schedules."
});
